// Clip polygon against the half-plane: points closer to 'owner' than to 'other'
int clipAgainstBisector(Point *in, int nin, Point owner, Point other, Point *out) {
    if (nin < 3) return 0;
    int nout = 0;
    Point mid = {(owner.x + other.x) / 2.0, (owner.y + other.y) / 2.0};
    double dx = owner.y - other.y;  // perpendicular direction
    double dy = other.x - owner.x;

    for (int i = 0; i < nin; i++) {
        Point cur = in[i];
        Point nxt = in[(i+1)%nin];
        double dcur = (cur.x - mid.x)*dx + (cur.y - mid.y)*dy;
        double dnxt = (nxt.x - mid.x)*dx + (nxt.y - mid.y)*dy;

        if (dcur >= -EPS) {
            out[nout++] = cur;
        }
        if ((dcur > EPS && dnxt < -EPS) || (dcur < -EPS && dnxt > EPS)) {
            // intersection
            double t = dcur / (dcur - dnxt);
            out[nout].x = cur.x + t*(nxt.x - cur.x);
            out[nout].y = cur.y + t*(nxt.y - cur.y);
            nout++;
        }
    }
    return nout;
}

