#define MAXN 105
#define EPS 1e-9

typedef struct { double x, y; } Point;

int n, m;
Point poly[MAXN], castles[MAXN];
Point tmp[MAXN];

// Clip polygon by half-plane: points p where (p - mid) . (b - a) <= 0
// i.e., closer to a than b
int clip(Point *in, int nin, Point a, Point b, Point *out) {
    // normal = b - a, mid = (a+b)/2
    // condition: (p - mid) . (b-a) <= 0
    // (p.x - mx)*dx + (p.y - my)*dy <= 0
    double mx = (a.x + b.x) / 2, my = (a.y + b.y) / 2;
    double dx = b.x - a.x, dy = b.y - a.y;
    int nout = 0;
    for (int i = 0; i < nin; i++) {
        Point p = in[i], q = in[(i+1) % nin];
        double dp = (p.x - mx)*dx + (p.y - my)*dy;
        double dq = (q.x - mx)*dx + (q.y - my)*dy;
        if (dp <= EPS) out[nout++] = p; // p is inside
        if ((dp < -EPS && dq > EPS) || (dp > EPS && dq < -EPS)) {
            // intersection
            double t = dp / (dp - dq);
            Point inter;
            inter.x = p.x + t * (q.x - p.x);
            inter.y = p.y + t * (q.y - p.y);
            out[nout++] = inter;
        }
    }
    return nout;
}

double polyArea(Point *p, int n) {
    double area = 0;
    for (int i = 0; i < n; i++) {
        int j = (i+1) % n;
        area += p[i].x * p[j].y - p[j].x * p[i].y;
    }
    return fabs(area) / 2.0;
}

