#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define EPS 1e-10

typedef struct {
    double x, y;
} Point;

static Point make_point(double x, double y) {
    Point p; p.x = x; p.y = y; return p;
}

static Point sub(Point a, Point b) {
    return make_point(a.x - b.x, a.y - b.y);
}

static double dot(Point a, Point b) {
    return a.x * b.x + a.y * b.y;
}

static double cross(Point a, Point b) {
    return a.x * b.y - a.y * b.x;
}

static double polygon_area(Point *p, int n) {
    double s = 0.0;
    for (int i = 0; i < n; i++) {
        int j = (i + 1) % n;
        s += cross(p[i], p[j]);
    }
    return fabs(s) * 0.5;
}

/*
Clip convex polygon poly[0..n-1] by half-plane:
dot(x, nvec) <= c
Returns new size, result stored in out.
*/
static int clip_halfplane(Point *poly, int n, Point nvec, double c, Point *out) {
    if (n == 0) return 0;
    int m = 0;
    for (int i = 0; i < n; i++) {
        Point A = poly[i];
        Point B = poly[(i + 1) % n];
        double fa = dot(A, nvec) - c;
        double fb = dot(B, nvec) - c;
        int ina = (fa <= EPS);
        int inb = (fb <= EPS);

        if (ina && inb) {
            out[m++] = B;
        } else if (ina && !inb) {
            Point d = sub(B, A);
            double denom = dot(d, nvec);
            double t = 0.0;
            if (fabs(denom) > EPS) t = (c - dot(A, nvec)) / denom;
            out[m++] = make_point(A.x + d.x * t, A.y + d.y * t);
        } else if (!ina && inb) {
            Point d = sub(B, A);
            double denom = dot(d, nvec);
            double t = 0.0;
            if (fabs(denom) > EPS) t = (c - dot(A, nvec)) / denom;
            out[m++] = make_point(A.x + d.x * t, A.y + d.y * t);
            out[m++] = B;
        }
    }
    return m;
}

int main(void) {
    int n, m;

    /*
      Expected input:
      n m
      n lines: polygon vertices in order
      m lines: castle coordinates

      Output:
      one line per castle: its Voronoi area inside the convex polygon
    */
    if (scanf("%d %d", &n, &m) != 2) return 0;

    Point *island = (Point *)malloc(sizeof(Point) * n);
    Point *castles = (Point *)malloc(sizeof(Point) * m);

    for (int i = 0; i < n; i++) {
        scanf("%lf %lf", &island[i].x, &island[i].y);
    }
    for (int i = 0; i < m; i++) {
        scanf("%lf %lf", &castles[i].x, &castles[i].y);
    }

    Point *poly1 = (Point *)malloc(sizeof(Point) * (n + m * 2 + 10));
    Point *poly2 = (Point *)malloc(sizeof(Point) * (n + m * 2 + 10));

    for (int i = 0; i < m; i++) {
        int sz = n;
        for (int k = 0; k < n; k++) poly1[k] = island[k];

        for (int j = 0; j < m; j++) {
            if (i == j) continue;

            /*
              Points closer to castles[i] than castles[j]:
              |x-a|^2 <= |x-b|^2
              2 x·(b-a) <= |b|^2 - |a|^2
            */
            Point a = castles[i], b = castles[j];
            Point nvec = make_point(2.0 * (b.x - a.x), 2.0 * (b.y - a.y));
            double c = b.x * b.x + b.y * b.y - a.x * a.x - a.y * a.y;

            sz = clip_halfplane(poly1, sz, nvec, c, poly2);
            Point *tmp = poly1; poly1 = poly2; poly2 = tmp;

            if (sz == 0) break;
        }

        double area = (sz == 0 ? 0.0 : polygon_area(poly1, sz));
        printf("%.10f\n", area);
    }

    free(island);
    free(castles);
    free(poly1);
    free(poly2);
    return 0;
}

