using namespace std;

typedef long double ld;
const ld EPS = 1e-12;

struct Point {
    ld x, y;
    Point() : x(0), y(0) {}
    Point(ld x, ld y) : x(x), y(y) {}
    Point operator+(const Point& p) const { return Point(x + p.x, y + p.y); }
    Point operator-(const Point& p) const { return Point(x - p.x, y - p.y); }
    Point operator*(ld s) const { return Point(x * s, y * s); }
    Point operator/(ld s) const { return Point(x / s, y / s); }
    ld cross(const Point& p) const { return x * p.y - y * p.x; }
    ld dot(const Point& p) const { return x * p.x + y * p.y; }
    ld length() const { return sqrtl(x * x + y * y); }
    Point normalize() const { return *this / length(); }
    Point perpendicular() const { return Point(-y, x); }
};

struct Line {
    Point p, v;
    Line() {}
    Line(Point p, Point v) : p(p), v(v) {}
    Point intersect(const Line& l) const {
        ld t = (l.p - p).cross(l.v) / v.cross(l.v);
        return p + v * t;
    }
    bool isParallel(const Line& l) const {
        return fabsl(v.cross(l.v)) < EPS;
    }
    bool isPointOnLeft(const Point& pt) const {
        return v.cross(pt - p) > EPS;
    }
};

ld polygonArea(const vector<Point>& poly) {
    ld area = 0;
    int n = poly.size();
    for (int i = 0; i < n; i++) {
        area += poly[i].cross(poly[(i + 1) % n]);
    }
    return fabsl(area) / 2.0;
}

vector<Point> halfplaneIntersection(vector<Line> lines) {
    // Sort by angle
    sort(lines.begin(), lines.end(), [](const Line& a, const Line& b) {
        ld ang1 = atan2l(a.v.y, a.v.x);
        ld ang2 = atan2l(b.v.y, b.v.x);
        if (fabsl(ang1 - ang2) < EPS) return a.v.cross(b.p - a.p) < -EPS;
        return ang1 < ang2;
    });

    // Remove duplicate parallel lines
    vector<Line> uniq;
    for (int i = 0; i < (int)lines.size(); i++) {
        if (i > 0) {
            ld ang1 = atan2l(lines[i].v.y, lines[i].v.x);
            ld ang2 = atan2l(lines[i-1].v.y, lines[i-1].v.x);
            if (fabsl(ang1 - ang2) < EPS) continue;
        }
        uniq.push_back(lines[i]);
    }

    int n = uniq.size();
    if (n < 3) return {};

    vector<Point> pts(n);
    vector<Line> dq(n);
    int l = 0, r = 0;
    dq[0] = uniq[0];

    for (int i = 1; i < n; i++) {
        while (l < r && !uniq[i].isPointOnLeft(pts[r-1])) r--;
        while (l < r && !uniq[i].isPointOnLeft(pts[l])) l++;
        dq[++r] = uniq[i];

        if (l < r) {
            if (dq[r].isParallel(dq[r-1])) return {};
            pts[r-1] = dq[r-1].intersect(dq[r]);
        }
    }

    while (l < r && !dq[l].isPointOnLeft(pts[r-1])) r--;
    if (r - l <= 1) return {};

    pts[r] = dq[r].intersect(dq[l]);

    vector<Point> result;
    for (int i = l; i <= r; i++) result.push_back(pts[i]);
    return result;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout << fixed << setprecision(10);

    int n;
    cin >> n;

    vector<Point> island(n);
    for (int i = 0; i < n; i++) {
        cin >> island[i].x >> island[i].y;
    }

    int m;
    cin >> m;

    vector<Point> castles(m);
    for (int i = 0; i < m; i++) {
        cin >> castles[i].x >> castles[i].y;
    }

    vector<ld> areas(m, 0.0);

    // For each castle, find its Voronoi cell within the island
    for (int i = 0; i < m; i++) {
        vector<Line> halfplanes;

        // Add island edges as constraints
        for (int j = 0; j < n; j++) {
            Point a = island[j];
            Point b = island[(j + 1) % n];
            Point v = b - a;
            // Ensure the half-plane contains the interior of the island
            Line l(a, v);
            Point center = Point(0, 0);
            for (auto& p : island) center = center + p;
            center = center / n;
            if (!l.isPointOnLeft(center)) {
                l.v = v * (-1.0);
            }
            halfplanes.push_back(l);
        }

        // Add bisector constraints with other castles
        for (int j = 0; j < m; j++) {
            if (i == j) continue;

            Point mid = (castles[i] + castles[j]) / 2.0;
            Point dir = castles[j] - castles[i];
            Point perp = dir.perpendicular();

            // The half-plane containing castle i
            Line bisector(mid, perp);
            if (!bisector.isPointOnLeft(castles[i])) {
                bisector.v = perp * (-1.0);
            }
            halfplanes.push_back(bisector);
        }

        vector<Point> cell = halfplaneIntersection(halfplanes);

        if (!cell.empty()) {
            // Clip to island using Sutherland-Hodgman
            vector<Point> clipped = cell;
            for (int j = 0; j < n; j++) {
                vector<Point> input = clipped;
                clipped.clear();
                if (input.empty()) break;

                Point a = island[j];
                Point b = island[(j + 1) % n];
                Point edge = b - a;

                for (int k = 0; k < (int)input.size(); k++) {
                    Point cur = input[k];
                    Point nxt = input[(k + 1) % input.size()];

                    bool curInside = edge.cross(cur - a) > -EPS;
                    bool nxtInside = edge.cross(nxt - a) > -EPS;

                    if (curInside) clipped.push_back(cur);
                    if (curInside != nxtInside) {
                        Line l1(a, edge);
                        Line l2(cur, nxt - cur);
                        if (!l1.isParallel(l2)) {
                            clipped.push_back(l1.intersect(l2));
                        }
                    }
                }
            }

            areas[i] = polygonArea(clipped);
        }
    }

    for (int i = 0; i < m; i++) {
        cout << areas[i] << "\n";
    }

    return 0;
}

