using namespace std;

typedef double ld;
typedef pair<ld,ld> P;

ld cross(P O, P A, P B) {
    return (A.first-O.first)*(B.second-O.second) - (A.second-O.second)*(B.first-O.first);
}

// Clip polygon by half-plane: keep points where cross(A,B,P) >= 0 (left side of AB)
vector<P> clip(vector<P> poly, P A, P B) {
    vector<P> res;
    int n = poly.size();
    for (int i = 0; i < n; i++) {
        P C = poly[i], D = poly[(i+1)%n];
        ld c1 = cross(A,B,C), c2 = cross(A,B,D);
        if (c1 >= 0) res.push_back(C);
        if ((c1 > 0 && c2 < 0) || (c1 < 0 && c2 > 0)) {
            // intersection of line CD with line AB
            ld t = cross(A,B,C) / (cross(A,B,C) - cross(A,B,D));
            res.push_back({C.first + t*(D.first-C.first), C.second + t*(D.second-C.second)});
        }
    }
    return res;
}

ld area(vector<P>& poly) {
    ld s = 0;
    int n = poly.size();
    for (int i = 0; i < n; i++) {
        s += poly[i].first * poly[(i+1)%n].second - poly[(i+1)%n].first * poly[i].second;
    }
    return abs(s) / 2.0;
}

