            if (i == j) continue;
            // perpendicular bisector of sites[i] and sites[j]
            // midpoint
            P mid = {(sites[i].first+sites[j].first)/2, (sites[i].second+sites[j].second)/2};
            // direction perpendicular to (sites[j]-sites[i]), rotated so sites[i] side is left
            // normal direction: from sites[i] to sites[j] is (dx,dy)
            // half-plane: keep points closer to sites[i]
            // A = mid, B = mid + perpendicular direction
