#include <bits/stdc++.h>
using namespace std;

static const double EPS = 1e-10;

struct Point {
    double x, y;
    Point() {}
    Point(double x_, double y_) : x(x_), y(y_) {}
    Point operator + (const Point& other) const { return Point(x + other.x, y + other.y); }
    Point operator - (const Point& other) const { return Point(x - other.x, y - other.y); }
    Point operator * (double k) const { return Point(x * k, y * k); }
};

double dot(const Point& a, const Point& b) {
    return a.x * b.x + a.y * b.y;
}

double cross(const Point& a, const Point& b) {
    return a.x * b.y - a.y * b.x;
}

double polygonArea(const vector<Point>& poly) {
    int n = (int)poly.size();
    if (n < 3) return 0.0;
    double s = 0;
    for (int i = 0; i < n; ++i) {
        int j = (i + 1) % n;
        s += cross(poly[i], poly[j]);
    }
    return fabs(s) * 0.5;
}

// Keep points p such that |p-a|^2 <= |p-b|^2
// Equivalent to 2 p·(b-a) <= |b|^2 - |a|^2
vector<Point> clipWithBisector(const vector<Point>& poly, const Point& a, const Point& b) {
    vector<Point> res;
    if (poly.empty()) return res;

    Point n = b - a;
    double c = (b.x * b.x + b.y * b.y - a.x * a.x - a.y * a.y) * 0.5;

    auto f = [&](const Point& p) -> double {
        return dot(p, n) - c; // <= 0 means closer to a than to b
    };

    int m = (int)poly.size();
    for (int i = 0; i < m; ++i) {
        Point P = poly[i];
        Point Q = poly[(i + 1) % m];
        double fP = f(P), fQ = f(Q);
        bool inP = fP <= EPS;
        bool inQ = fQ <= EPS;

        if (inP && inQ) {
            res.push_back(Q);
        } else if (inP && !inQ) {
            Point d = Q - P;
            double denom = dot(d, n);
            if (fabs(denom) > EPS) {
                double t = (c - dot(P, n)) / denom;
                res.push_back(P + d * t);
            }
        } else if (!inP && inQ) {
            Point d = Q - P;
            double denom = dot(d, n);
            if (fabs(denom) > EPS) {
                double t = (c - dot(P, n)) / denom;
                res.push_back(P + d * t);
            }
            res.push_back(Q);
        }
    }

    // Remove consecutive duplicate points
    vector<Point> clean;
    for (auto &p : res) {
        if (clean.empty() || hypot(clean.back().x - p.x, clean.back().y - p.y) > 1e-9)
            clean.push_back(p);
    }
    if (clean.size() >= 2 &&
        hypot(clean.front().x - clean.back().x, clean.front().y - clean.back().y) <= 1e-9) {
        clean.pop_back();
    }
    return clean;
}

