    return 0;
}

import java.util.*;
import java.awt.geom.*;

public class VoronoiIsland {
    static final double EPS = 1e-9;

    static class Point {
        double x, y;
        Point(double x, double y) { this.x = x; this.y = y; }
    }

    static double cross(Point a, Point b, Point c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    }

    static List<Point> clipPolygon(List<Point> poly, Point a, Point b) {
        // Clip polygon with half-plane: points on left side of directed line a->b
        List<Point> result = new ArrayList<>();
        int n = poly.size();
        for (int i = 0; i < n; i++) {
            Point cur = poly.get(i);
            Point next = poly.get((i + 1) % n);
            double curSide = cross(a, b, cur);
            double nextSide = cross(a, b, next);
            if (curSide >= -EPS) result.add(cur);
            if ((curSide > EPS && nextSide < -EPS) || (curSide < -EPS && nextSide > EPS)) {
                double t = curSide / (curSide - nextSide);
                result.add(new Point(cur.x + t * (next.x - cur.x), cur.y + t * (next.y - cur.y)));
            }
        }
        return result;
    }

    static double polygonArea(List<Point> poly) {
        double area = 0;
        int n = poly.size();
        for (int i = 0; i < n; i++) {
            Point a = poly.get(i);
            Point b = poly.get((i + 1) % n);
            area += a.x * b.y - a.y * b.x;
        }
        return Math.abs(area) / 2.0;
    }

