import java.io.*;
import java.util.*;

/*
 * Voronoi on a convex polygon:
 * For each site (castle), its region inside the island is the intersection of the island
 * with all half-planes closer to this site than to every other site.
 *
 * For two sites A and B, points X satisfying dist(X,A) <= dist(X,B) form a half-plane:
 *   2(B-A) · X <= |B|^2 - |A|^2
 *
 * Since the island is convex, each region can be obtained by repeatedly clipping the polygon
 * with these half-planes (Sutherland-Hodgman). Then compute polygon area.
 *
 * Input format assumed:
 *   n m
 *   n lines: xi yi          (vertices of convex island in order)
 *   m lines: xi yi          (castles)
 *
 * Output:
 *   one line per castle: its area
 *
 * Areas are printed with 10 digits after decimal point.
 */
public class Main {
    static final double EPS = 1e-9;

    static class Point {
        double x, y;
        Point(double x, double y) { this.x = x; this.y = y; }
        Point add(Point o) { return new Point(x + o.x, y + o.y); }
        Point sub(Point o) { return new Point(x - o.x, y - o.y); }
        Point mul(double k) { return new Point(x * k, y * k); }
    }

    static double dot(Point a, Point b) {
        return a.x * b.x + a.y * b.y;
    }

    static double area(List<Point> poly) {
        int n = poly.size();
        if (n < 3) return 0.0;
        double s = 0;
        for (int i = 0; i < n; i++) {
            Point a = poly.get(i);
            Point b = poly.get((i + 1) % n);
            s += a.x * b.y - a.y * b.x;
        }
        return Math.abs(s) * 0.5;
    }

    // Clip polygon by half-plane n·x <= c
    static List<Point> clip(List<Point> poly, Point n, double c) {
        List<Point> res = new ArrayList<>();
        int sz = poly.size();
        if (sz == 0) return res;

        for (int i = 0; i < sz; i++) {
            Point A = poly.get(i);
            Point B = poly.get((i + 1) % sz);

            double fa = dot(n, A) - c;
            double fb = dot(n, B) - c;

            boolean ina = fa <= EPS;
            boolean inb = fb <= EPS;

            if (ina && inb) {
                res.add(B);
            } else if (ina && !inb) {
                Point inter = intersectSegmentLine(A, B, n, c);
                if (inter != null) res.add(inter);
            } else if (!ina && inb) {
                Point inter = intersectSegmentLine(A, B, n, c);
                if (inter != null) res.add(inter);
                res.add(B);
            }
        }
        return res;
    }

    // Segment AB with line n·x = c
    static Point intersectSegmentLine(Point A, Point B, Point n, double c) {
        Point d = B.sub(A);
        double denom = dot(n, d);
        if (Math.abs(denom) < EPS) return null; // parallel; should not matter in clipping logic
        double t = (c - dot(n, A)) / denom;
        return A.add(d.mul(t));
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int m = fs.nextInt();

        List<Point> island = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            island.add(new Point(fs.nextDouble(), fs.nextDouble()));
        }

        Point[] castles = new Point[m];
        for (int i = 0; i < m; i++) {
            castles[i] = new Point(fs.nextDouble(), fs.nextDouble());
        }

        StringBuilder out = new StringBuilder();

        for (int i = 0; i < m; i++) {
            List<Point> region = new ArrayList<>(island);

            for (int j = 0; j < m; j++) {
                if (i == j) continue;

                Point a = castles[i];
                Point b = castles[j];

                // Half-plane: 2(b-a)·x <= |b|^2 - |a|^2
                Point normal = new Point(2.0 * (b.x - a.x), 2.0 * (b.y - a.y));
                double c = b.x * b.x + b.y * b.y - a.x * a.x - a.y * a.y;

                region = clip(region, normal, c);
                if (region.isEmpty()) break;
            }

            out.append(String.format(Locale.US, "%.10f%n", area(region)));
        }

        System.out.print(out);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            if (c == -1) return null;
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

