def cross(o, a, b):
    return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])

def convex_hull(points):
    points = sorted(set(points))
    if len(points) <= 1:
        return points
    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]

def line_intersection(p1, p2, p3, p4):
    x1,y1 = p1
    x2,y2 = p2
    x3,y3 = p3
    x4,y4 = p4
    denom = (x1-x2)*(y3-y4) - (y1-y2)*(x3-x4)
    if abs(denom) < 1e-12:
        return None
    t = ((x1-x3)*(y3-y4) - (y1-y3)*(x3-x4)) / denom
    x = x1 + t*(x2-x1)
    y = y1 + t*(y2-y1)
    return (x, y)

def perpendicular_bisector(a, b):
    mx = (a[0]+b[0])/2.0
    my = (a[1]+b[1])/2.0
    dx = b[0]-a[0]
    dy = b[1]-a[1]
    # direction perpendicular to ab
    return (mx, my), (mx - dy, my + dx)

def point_in_convex_polygon(pt, poly):
    n = len(poly)
    for i in range(n):
        if cross(poly[i], poly[(i+1)%n], pt) < -1e-12:
            return False
    return True

def clip_polygon_by_halfplane(poly, a, b):
    # keep points where cross(a,b,pt) >= 0
    if len(poly) == 0:
        return []
    new_poly = []
    n = len(poly)
    for i in range(n):
        p = poly[i]
        q = poly[(i+1)%n]
        cp = cross(a, b, p)
        cq = cross(a, b, q)
        if cp >= -1e-12:
            new_poly.append(p)
        if (cp > 1e-12 and cq < -1e-12) or (cp < -1e-12 and cq > 1e-12):
            inter = line_intersection(a, b, p, q)
            if inter:
                new_poly.append(inter)
    return new_poly

def polygon_area(poly):
    if len(poly) < 3:
        return 0.0
    area = 0.0
    n = len(poly)
    for i in range(n):
        x1,y1 = poly[i]
        x2,y2 = poly[(i+1)%n]
        area += x1*y2 - x2*y1
    return abs(area)/2.0

