    results = []
    for i, castle in enumerate(castles):
        cell = island[:]
        for j, other in enumerate(castles):
            if i == j:
                continue
            mid, dir_end = perpendicular_bisector(castle, other)
            # half-plane containing castle: cross(mid, dir_end, castle) >= 0
            a, b = mid, dir_end
            if cross(a, b, castle) < 0:
                # flip direction
                a, b = mid, (mid[0] + (mid[0]-dir_end[0]), mid[1] + (mid[1]-dir_end[1]))
            cell = clip_polygon_by_halfplane(cell, a, b)
