EPS = 1e-10

def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]

def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])

def add(a, b):
    return (a[0] + b[0], a[1] + b[1])

def mul(a, t):
    return (a[0] * t, a[1] * t)

def polygon_area(poly):
    n = len(poly)
    if n < 3:
        return 0.0
    s = 0.0
    for i in range(n):
        x1, y1 = poly[i]
        x2, y2 = poly[(i + 1) % n]
        s += x1 * y2 - x2 * y1
    return abs(s) * 0.5

def line_intersection_with_segment(a, b, f1, f2):
    # Segment a->b, scalar values f(a)=f1, f(b)=f2 for a line f(x)=0
    # assumes segment intersects the line
    t = f1 / (f1 - f2)
    return (a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t)

def clip_polygon_halfplane(poly, nvec, c):
    # Keep points p with dot(nvec, p) <= c
    if not poly:
        return []
    res = []
    m = len(poly)

    def val(p):
        return nvec[0] * p[0] + nvec[1] * p[1] - c

    for i in range(m):
        cur = poly[i]
        nxt = poly[(i + 1) % m]
        f1 = val(cur)
        f2 = val(nxt)
        in1 = f1 <= EPS
        in2 = f2 <= EPS

        if in1 and in2:
            res.append(nxt)
        elif in1 and not in2:
            inter = line_intersection_with_segment(cur, nxt, f1, f2)
            res.append(inter)
        elif not in1 and in2:
            inter = line_intersection_with_segment(cur, nxt, f1, f2)
            res.append(inter)
            res.append(nxt)
        # else both out: add nothing
    return res

def voronoi_cell_area(island, sites, idx):
    cell = island[:]
    sx, sy = sites[idx]
    for j, (tx, ty) in enumerate(sites):
        if j == idx:
            continue
        # Keep points closer to s than to t:
        # |p-s|^2 <= |p-t|^2
        # 2 (t-s) · p <= |t|^2 - |s|^2
        nvec = (2.0 * (tx - sx), 2.0 * (ty - sy))
        c = tx * tx + ty * ty - sx * sx - sy * sy
        cell = clip_polygon_halfplane(cell, nvec, c)
        if len(cell) < 3:
            return 0.0
    return polygon_area(cell)

